package com.hospital.appointment.service;

import com.hospital.appointment.client.DoctorServiceClient;
import com.hospital.appointment.client.PatientServiceClient;
import com.hospital.appointment.dto.AppointmentResponseDto;
import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.mockito.Mockito.doThrow;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    // GreyTest trace: getAppointmentById | patient lookup throws and fallback response is returned | BR-006 -> TP-002 -> TC-022
    @Test
    void getAppointmentById_returnsAppointmentOnlyWhenEnrichmentThrows() {
        // Arrange
        AppointmentService sut = new AppointmentService(appointmentRepository, patientServiceClient, doctorServiceClient);
        Appointment appointment = new Appointment();
        appointment.setId(1001L);
        appointment.setPatientId(201L);
        appointment.setDoctorId(301L);
        appointment.setAppointmentDate(LocalDate.of(2026, 11, 2));
        appointment.setAppointmentTime(LocalTime.of(9, 30));
        appointment.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        appointment.setReason("Khám định kỳ");
        appointment.setNotes("Ghi chú");
        when(appointmentRepository.findById(1001L)).thenReturn(Optional.of(appointment));
        doThrow(new RuntimeException()).when(patientServiceClient).getPatientById(201L);

        // Act
        AppointmentResponseDto result = sut.getAppointmentById(1001L);

        // Assert
        assertNotNull(result);
        assertEquals(1001L, result.getId());
        assertEquals(201L, result.getPatientId());
        assertEquals(301L, result.getDoctorId());
        assertEquals(LocalDate.of(2026, 11, 2), result.getAppointmentDate());
        assertEquals(LocalTime.of(9, 30), result.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, result.getStatus());
        assertEquals("Khám định kỳ", result.getReason());
        assertEquals("Ghi chú", result.getNotes());
        assertNull(result.getPatientName());
        assertNull(result.getDoctorName());
        assertNull(result.getDoctorSpecialization());
        verify(appointmentRepository).findById(1001L);
        verify(patientServiceClient).getPatientById(201L);
    }
}

