        assertEquals("Dr. Bình Trần", result.getDoctorName());
        assertEquals("Nội khoa", result.getDoctorSpecialization());
        verify(appointmentRepository).findById(id);
        verify(appointmentRepository).save(same(appointment));
        verify(patientServiceClient).getPatientById(2001L);
