    @Test
    void createAppointment_ProvidedNoShowStatus_PreservesStatusAndRequestFields() {
        // Arrange
        Long patientId = 101L;
        Long doctorId = 202L;
        LocalDate appointmentDate = LocalDate.of(2030, 5, 20);
        LocalTime appointmentTime = LocalTime.of(10, 30);
        AppointmentRequestDto requestDto = new AppointmentRequestDto(
                patientId, doctorId, appointmentDate, appointmentTime,
                "Khám định kỳ", null, Appointment.AppointmentStatus.NO_SHOW);
        PatientDto patient = new PatientDto(101L, "An", "Nguyen", "an@example.test", "555-0101");
        DoctorDto doctor = new DoctorDto(202L, "Binh", "Tran", "Cardiology", true);
        when(patientServiceClient.getPatientById(patientId)).thenReturn(patient);
        when(doctorServiceClient.getDoctorById(doctorId)).thenReturn(doctor);
        when(appointmentRepository.findConflictingAppointment(doctorId, appointmentDate, appointmentTime))
                .thenReturn(Optional.empty());
        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> {
            Appointment submitted = invocation.getArgument(0);
            submitted.setId(303L);
            return submitted;
