        assertEquals("Dr. Bình Trần", result.getDoctorName());
        assertEquals("Tim mạch", result.getDoctorSpecialization());
        verify(appointmentRepository).findById(303L);
        verify(patientServiceClient).getPatientById(101L);
        verify(doctorServiceClient).getDoctorById(202L);
