package com.hospital.appointment.service;

import com.hospital.appointment.client.DoctorServiceClient;
import com.hospital.appointment.client.PatientServiceClient;
import com.hospital.appointment.dto.AppointmentResponseDto;
import com.hospital.appointment.dto.DoctorDto;
import com.hospital.appointment.dto.PatientDto;
import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    // GreyTest trace: getAllAppointments | STMT-2 | BR-025 -> TP-020 -> TC-018
    @Test
    void getAllAppointments_returnsEnrichedResponsesInRepositoryOrder() {
        // Arrange
        AppointmentService sut = new AppointmentService(appointmentRepository, patientServiceClient, doctorServiceClient);
        Appointment first = new Appointment();
        first.setId(303L);
        first.setPatientId(101L);
        first.setDoctorId(202L);
        first.setAppointmentDate(LocalDate.of(2030, 5, 20));
        first.setAppointmentTime(LocalTime.of(9, 30));
        first.setStatus(Appointment.AppointmentStatus.CONFIRMED);
        first.setReason("Khám định kỳ");
        first.setNotes(null);

        Appointment second = new Appointment();
        second.setId(304L);
        second.setPatientId(102L);
        second.setDoctorId(203L);
        second.setAppointmentDate(LocalDate.of(2030, 5, 21));
        second.setAppointmentTime(LocalTime.of(11, 0));
        second.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        second.setReason("Tư vấn");
        second.setNotes(null);

        when(appointmentRepository.findAll()).thenReturn(Arrays.asList(first, second));
        when(patientServiceClient.getPatientById(101L)).thenReturn(new PatientDto(101L, "An", "Nguyễn", "an@example.test", "0900000001"));
        when(patientServiceClient.getPatientById(102L)).thenReturn(new PatientDto(102L, "Chi", "Lê", "chi@example.test", "0900000002"));
        when(doctorServiceClient.getDoctorById(202L)).thenReturn(new DoctorDto(202L, "Bình", "Trần", "Tim mạch", true));
        when(doctorServiceClient.getDoctorById(203L)).thenReturn(new DoctorDto(203L, "Dũng", "Phạm", "Nội khoa", true));

        // Act
        List<AppointmentResponseDto> result = sut.getAllAppointments();

        // Assert
        assertEquals(2, result.size());
        AppointmentResponseDto firstResult = result.get(0);
        assertEquals(303L, firstResult.getId());
        assertEquals(101L, firstResult.getPatientId());
        assertEquals(202L, firstResult.getDoctorId());
        assertEquals("An Nguyễn", firstResult.getPatientName());
        assertEquals("Dr. Bình Trần", firstResult.getDoctorName());
        assertEquals("Tim mạch", firstResult.getDoctorSpecialization());
        assertEquals(LocalDate.of(2030, 5, 20), firstResult.getAppointmentDate());
        assertEquals(LocalTime.of(9, 30), firstResult.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.CONFIRMED, firstResult.getStatus());
        assertEquals("Khám định kỳ", firstResult.getReason());
        assertNull(firstResult.getNotes());

        AppointmentResponseDto secondResult = result.get(1);
        assertEquals(304L, secondResult.getId());
        assertEquals(102L, secondResult.getPatientId());
        assertEquals(203L, secondResult.getDoctorId());
        assertEquals("Chi Lê", secondResult.getPatientName());
        assertEquals("Dr. Dũng Phạm", secondResult.getDoctorName());
        assertEquals("Nội khoa", secondResult.getDoctorSpecialization());
        assertEquals(LocalDate.of(2030, 5, 21), secondResult.getAppointmentDate());
        assertEquals(LocalTime.of(11, 0), secondResult.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, secondResult.getStatus());
        assertEquals("Tư vấn", secondResult.getReason());
        assertNull(secondResult.getNotes());

        verify(appointmentRepository).findAll();
        verify(patientServiceClient).getPatientById(101L);
        verify(patientServiceClient).getPatientById(102L);
        verify(doctorServiceClient).getDoctorById(202L);
        verify(doctorServiceClient).getDoctorById(203L);
    }
}
